-- Editable site settings that used to be written into the code (src/data): the FC Lads+ price, trial
-- and perks; social links (incl. the Discord invite); the Home "hard truth" section; Discord channels
-- and rules. Edited on the posting board (Site settings). The defaults are the values the site showed.

alter table public.site_settings
  add column plus jsonb not null default $json${"price":29,"currency":"USD","trialDays":14,"perks":[{"key":"guides","title":"Guides & video series","description":"Every guide and {season} video collection, with slider codes and controller inputs."},{"key":"discord","title":"Private Discord","description":"Members-only channels with the creators and pro players."},{"key":"creators","title":"Creator access","description":"Ask the Lads directly. Squad and chemistry fixes every week."},{"key":"trading","title":"Trading posts","description":"Members-only market calls from the Lads, with screenshots."},{"key":"review","title":"Monthly review","description":"A 1-on-1 video review of your own FUT Champs gameplay."}]}$json$::jsonb,
  add column socials jsonb not null default $json${"youtube":"","instagram":"","x":"","tiktok":"","discord":""}$json$::jsonb,
  add column hard_truth jsonb not null default $json$[{"problem":"A new patch drops.","answerTitle":"Same-day patch breakdowns.","answer":"We read the notes, then test every change in-game the same day. You get a plain-English summary of what actually changed and what to do about it.","creatorSlug":"stefan","cta":{"label":"Read patch breakdowns","href":"/learn?category=fc-updates"}},{"problem":"The meta changes.","answerTitle":"A weekly meta breakdown.","answer":"Every week the Lads break down the formations, tactics and card types winning right now in FUT Champs, so you always know what the top players are using.","creatorSlug":"hobs","cta":{"label":"Browse meta guides","href":"/learn?category=meta-players"}},{"problem":"A player suddenly becomes broken.","answerTitle":"Tested before you spend.","answer":"We put them through real Champs games, tell you if they're worth the coins, and show cheaper alternatives that play almost the same.","creatorSlug":"hobs","cta":{"label":"Watch the video series","href":"/learn/collections"}},{"problem":"A tactic stops working.","answerTitle":"Updated tactics and slider codes.","answer":"When a formation gets figured out, we rebuild it. New custom tactics, player instructions and slider values, tested in Elite Division.","creatorSlug":"stefan","cta":{"label":"Browse tactics guides","href":"/learn?category=tactics"}},{"problem":"The market moves.","answerTitle":"Market calls as they happen.","answer":"Wessam and the Lads post what to buy, when to sell and why, with screenshots, so you can build coins without living on the transfer market.","creatorSlug":"wessam","cta":{"label":"See the trading posts","href":"/trading"}}]$json$::jsonb,
  add column discord jsonb not null default $json${"channels":[{"name":"tactics-room","label":"Tactics","description":"Formations, custom tactics and how to beat the press. Ask before you change your setup.","pinned":"Patch 1.08: 4-3-2-1 setup and slider codes"},{"name":"show-your-squad","label":"Squads","description":"Post your team for feedback on chemistry, upgrades and where to spend coins next.","pinned":"How to share your squad link"},{"name":"ask-the-lads","label":"Creator Q&A","description":"Questions for Stefan, Hobs, Wessam and Lizzy. The Lads answer every day.","pinned":"Read this before you ask: what to include"},{"name":"market-talk","label":"Trading","description":"Price alerts, SBC investments and quick trading questions for Wessam.","pinned":"This week: fodder before Friday's SBC"},{"name":"help","label":"Support","description":"Problems with your account, Discord role or billing. The team replies within a day."}],"rules":["Be respectful. No abuse, hate speech or harassment.","No selling or buying coins, accounts or boosting.","Don't share FC Lads+ guides, videos or trading posts outside the server.","Keep posts in the right channel."]}$json$::jsonb;

alter table public.site_settings
  add constraint site_settings_plus_shape check (jsonb_typeof(plus) = 'object' and jsonb_typeof(plus -> 'perks') = 'array'),
  add constraint site_settings_socials_shape check (jsonb_typeof(socials) = 'object'),
  add constraint site_settings_hard_truth_shape check (jsonb_typeof(hard_truth) = 'array'),
  add constraint site_settings_discord_shape check (jsonb_typeof(discord) = 'object');
